import{z as l,x as B,o as E,c as A,q as i,j as o,D as e,d as r,s,S as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"发布工程：版本与分支","description":"","frontmatter":{"title":"发布工程：版本与分支","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/eco-release-versioning.md","filePath":"llm/eco-release-versioning.md","lastUpdated":1791063341000}'),d={name:"llm/eco-release-versioning.md"};function m(p,a,g,c,F,h){const n=B("Mermaid");return E(),A("div",null,[a[2]||(a[2]=i('<h1 id="发布工程-版本与分支" tabindex="-1">发布工程：版本与分支 <a class="header-anchor" href="#发布工程-版本与分支" aria-label="Permalink to &quot;发布工程：版本与分支&quot;">​</a></h1><div class="epigraph"><p>「模型更新了」不是一条发布信息；能让下游精确钉住、评测可锚、事故可回滚的那一串哈希才是。</p><footer>—— 据 Hugging Face Hub 的 revision 机制与 Llama、Qwen 两族的版本命名实践整理</footer></div><p><a href="/llm/eco-model-data-cards">上一课</a>把发布包配齐，卡与权重的对应靠 revision 锚定——「锚定」这个词还没展开。模型会持续更新：大版本重训，小版本续训，变体矩阵越铺越宽，量化文件成倍增加。本课写发布工程的版本语义：revision、tag、变体命名与弃用，让<a href="/llm/eco-model-data-cards">模型卡</a>承诺的每一格都钉在不可变的地址上。后课的基准公信力，要靠这里的版本纪律才有资格谈比较。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>下游最常见的翻车是「追 main」：生产管线永远拉最新 revision，某天 tokenizer 或聊天模板悄悄变了，同一个提示的输出漂移，而没人动过配置。第二类翻车是变体歧义：写 <code>llama-3</code> 到底指 8B 基座还是 70B 指令版、哪个量化、哪次更新？第三类是回滚困境：出了事故想退回上一版，发现旧文件被覆盖，或者「上一版」只是记忆里的一个名字。缺的是一套让地址不可变、语义可查、变更可追溯的发布约定。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>四条约定。<strong>revision 不可变</strong>：托管平台按内容寻址，任何一次上传都是一个哈希；发布时在不可变 revision 上打 tag，生产管线 pin 哈希而不追 main。<strong>语义命名</strong>：族名加大版本加大版本内序号加变体后缀——Llama 3 之后是 3.1、3.2、3.3，<a href="/llm/qwen-evolution">Qwen</a> 从 1.5、2 走到 2.5，同一套模式：小数点版本延续 tokenizer 与大部分配方，大版本才换 tokenizer 与重训。基座、指令、专用变体用后缀分开，基座与指令模型永远不共用一个地址。<strong>变更分级</strong>：加文件是小改；改聊天模板、改 tokenizer、改推荐解码参数是破坏性变更，单独发版并在 changelog 写明。<strong>弃用政策</strong>：旧 revision 保留多久、哪个 tag 会删，写进文档，别让下游的 pin 悄悄失效。<span class="marginnote">revision 可以类比成图书的版次号：按文件内容算出的哈希，内容变一点、号就完全不同，所以同一 revision 永远指向同一份文件。而「main」像书架上「最新一排」的标签，随时会被新书换掉——生产系统引用前者是钉死的地址，引用后者是赌运气。</span></p>',7)),(E(),o(t,null,{default:e(()=>[s(n,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEV%5B%22%E5%BC%80%E5%8F%91%EF%BC%9Amain%20%E5%8F%AF%E5%8F%98%22%5D%20--%3E%20REL%5B%22%E5%8F%91%E5%B8%83%EF%BC%9A%E4%B8%8D%E5%8F%AF%E5%8F%98%20revision%22%5D%0A%20%20REL%20--%3E%20TAG%5B%22%E6%89%93%20tag%20%E4%B8%8E%20changelog%22%5D%0A%20%20TAG%20--%3E%20VAR%5B%22%E5%8F%98%E4%BD%93%EF%BC%9A%E5%9F%BA%E5%BA%A7%20%2F%20%E6%8C%87%E4%BB%A4%20%2F%20%E9%87%8F%E5%8C%96%E5%90%84%E5%8D%A0%E5%9C%B0%E5%9D%80%22%5D%0A%20%20VAR%20--%3E%20PIN%5B%22%E4%B8%8B%E6%B8%B8%20pin%20%E5%93%88%E5%B8%8C%22%5D%0A%20%20PIN%20--%3E%20RB%5B%22%E4%BA%8B%E6%95%85%E5%9B%9E%E6%BB%9A%EF%BC%9A%E6%8D%A2%E5%9B%9E%E6%97%A7%20revision%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>版本工程的本质是给评测与回滚一个<strong>不可变锚</strong>。评测协议是模型、harness、解码、套件四位一体，版本钉住第一位，比较才有差分；这也是为什么权重文件用 <a href="/llm/safetensors-format">safetensors</a> 这类带完整性校验的格式，分片索引与哈希随 revision 走，钉哈希等于钉内容。回滚同理：事故处置是「把指针换回旧 revision」，不是「重新生成一份差不多的」，前者分钟级且可审计，后者是二次事故。量化变体让矩阵再乘一个维度：<a href="/llm/gguf">GGUF</a> 的每个量化等级都对应源权重的某个 revision，发布时成对登记，丢了对，下游拿到的量化就成了无源之水。</p><p><span class="marginnote">Llama 3 到 3.1 扩上下文并加入 405B，3.2 加小尺寸与视觉，3.3 更新 70B：小数点版本在同一 tokenizer 与配方系内演进。版本号的语义要写进卡，不能指望读者从号段猜。</span></p><p>发布方改动面前，先做一次变更分级：</p>',4)),(E(),o(t,null,{default:e(()=>[s(n,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20CH%5B%22%E5%8F%91%E5%B8%83%E6%96%B9%E8%A6%81%E6%94%B9%E7%82%B9%E4%BB%80%E4%B9%88%22%5D%20--%3E%20Q1%7B%22%E5%8A%A8%20tokenizer%20%E6%88%96%E8%81%8A%E5%A4%A9%E6%A8%A1%E6%9D%BF%EF%BC%9F%22%7D%0A%20%20Q1%20--%3E%7C%E6%98%AF%7C%20BRK%5B%22%E7%A0%B4%E5%9D%8F%E6%80%A7%E5%8F%98%E6%9B%B4%EF%BC%9A%E5%8D%95%E7%8B%AC%E5%8F%91%E7%89%88%22%5D%0A%20%20Q1%20--%3E%7C%E5%90%A6%7C%20Q2%7B%22%E6%94%B9%E6%8E%A8%E8%8D%90%E8%A7%A3%E7%A0%81%E6%88%96%E6%A8%A1%E6%9D%BF%E9%85%8D%E7%BD%AE%EF%BC%9F%22%7D%0A%20%20Q2%20--%3E%7C%E6%98%AF%7C%20BRK%0A%20%20Q2%20--%3E%7C%E5%90%A6%7C%20MINOR%5B%22%E5%B0%8F%E6%94%B9%EF%BC%9A%E5%8A%A0%E6%96%87%E4%BB%B6%E6%88%96%E8%A1%A5%E6%96%87%E6%A1%A3%22%5D%0A%20%20MINOR%20--%3E%20KEEP%5B%22%E5%8E%9F%E7%89%88%E6%9C%AC%E5%86%85%E8%BF%BD%E5%8A%A0%EF%BC%8Cchangelog%20%E8%AE%B0%E4%B8%80%E8%A1%8C%22%5D%0A%20%20BRK%20--%3E%20NEW%5B%22%E6%96%B0%E5%9C%B0%E5%9D%80%E5%8F%91%E5%B8%83%EF%BC%8C%E4%B8%8B%E6%B8%B8%E8%87%AA%E8%A1%8C%E8%AF%84%E4%BC%B0%E5%8D%87%E7%BA%A7%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i('<p><span class="marginnote">为什么量化文件要成对登记源 revision？同一底座两个版本量出来的 GGUF 可能差好几个点，下游拿着一份无出处的量化，复现不出你报的分数，责任都说不清。发布时把「量化文件 ↔ 源 revision ↔ 量化等级」三个字段一起登记，是成本最低的自证——缺了这一步，量化就成了无源之水。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>权重发布不是软件语义化版本：模型没有「接口不变」的承诺，输出分布随任何一次更新漂移，pin 了哈希也只保证内容一致，不保证行为一致——行为变化靠评测回归兜底，那是下一课的事。<span class="marginnote">初学者容易以为「钉了哈希就万事大吉」。钉哈希只保证拿到的文件一模一样，不保证模型行为永远一样——推理库升级、模板渲染器换版本，同样的权重照样能输出漂移。内容一致与行为一致是两道题：前者靠版本纪律，后者要靠每次升级跑一遍评测回归。</span>版本号的含义由发布方定义，本课给的只是社区已收敛的模式，读者遇到新族先读 changelog 再用。内部开发分支可以激进，发布面必须收敛：main 上的实验 checkpoint 一旦被外部引用，就从「临时」变成「事实上的版本」，撤回成本极高。最后，版本纪律约束的是发布方；下游不 pin 哈希，再好的发布工程也救不了生产管线。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四条约定：revision 不可变、发布打 tag、变体各占地址、弃用写明政策。</li><li>生产 pin 哈希不追 main；版本语义（小数点延续配方、大版本重训换 tokenizer）写进 changelog 与卡。</li><li>破坏性变更——聊天模板、tokenizer、推荐解码——单独发版。</li><li>评测与回滚都依赖不可变锚：钉哈希保证内容一致，行为一致靠评测回归。</li><li>safetensors 的校验与 GGUF 量化的源 revision 成对登记，量化文件不能成无源之水。</li><li>出处：Hugging Face Hub revision 机制；Llama 3.x 与 Qwen 1.5–2.5 版本命名实践，按本课程整理。</li></ul>',5))])}const D=l(d,[["render",m]]);export{_ as __pageData,D as default};
